public class MatrixChainSolverTest {

    @FunctionalInterface
    interface ThrowingRunnable {
        void run() throws Exception;
    }

    static void assertThrows(Class<? extends Throwable> expectedType, ThrowingRunnable runnable) {
        boolean threw = false;
        try {
            runnable.run();
        } catch (Throwable t) {
